using Purview.Results.SourceGenerator.Analyzers;

namespace Purview.Results.SourceGenerator;

/// <summary>
/// Discovery tests for unions generated by <c>Purview.Unions</c>. A Roslyn generator never sees another
/// generator's output, so a <c>[GenerateUnion]</c> target has no visible <c>[Union]</c> attribute and no
/// visible constructors in this compilation; its cases must come from the source-visible list instead.
/// </summary>
/// <remarks>
/// The tests declare a stand-in <c>Purview.Unions.GenerateUnionAttribute</c> (and, where the generated
/// helpers need a case-to-union conversion that the real generator would emit, source-visible conversion
/// operators). The two-generator integration test is recorded as an interop follow-up, because
/// <c>Purview.Unions</c> is not on a CI-safe package feed yet.
/// </remarks>
public class GenerateUnionDiscoveryTests
	: TUnitSourceGeneratorTestBase<ResultsSourceGenerator, ResultsSourceGeneratorTestOptions>
{
	[Test]
	public async Task GenerateAsync_GivenGenerateUnionTypeofListAndNoConstructors_EmitsTheCaseHelpers(
		CancellationToken cancellationToken
	)
	{
		// Arrange
		// The type has no source constructor and no [Union] attribute: exactly what this generator sees for
		// a union another generator emits. The implicit operators stand in for the conversion the union
		// generator's output provides at the final compilation.
		const string source = """
			using Purview.Unions;

			namespace Test
			{
				public readonly record struct SourceCase(int Id);

				public readonly record struct OtherCase(string Reason);

				[GenerateUnion(typeof(SourceCase), typeof(OtherCase))]
				[GenerateResult]
				public readonly struct GeneratedError
				{
					readonly object? _value;

					GeneratedError(object? value) => _value = value;

					public static implicit operator GeneratedError(SourceCase value) => new(value);

					public static implicit operator GeneratedError(OtherCase value) => new(value);

					public object? Value => _value;
				}
			}
			""";

		// Act
		using var result = await GenerateAsync(
			[TestSources.GenerateUnionAttributeDeclaration, source],
			cancellationToken
		);

		// Assert
		result.AssertNoCompilationErrors();
		await Assert.That(result).HasGeneratedClass("GeneratedErrorResultExtensions");

		var generated = result.AssertSingleGeneratedSource();
		await Assert.That(generated).Contains("this global::Test.SourceCase error");
		await Assert.That(generated).Contains("this global::Test.OtherCase error");
		await Assert.That(generated).Contains("extension(global::Test.GeneratedError)");
		await Assert.That(generated).Contains("> Failure(");
		await Assert.That(generated).Contains("> Failure<TValue>(");
		await Assert.That(generated).Contains("> Success()");
	}

	[Test]
	public async Task GenerateAsync_GivenGenerateUnionAttributeAndConstructors_UsesTheTypeofList(
		CancellationToken cancellationToken
	)
	{
		// Arrange
		// ConstructorOnlyCase is a public single-parameter constructor but is deliberately absent from the
		// typeof list, so it proves the attribute list wins over the constructor list.
		const string source = """
			using Purview.Unions;

			namespace Test
			{
				public readonly record struct SourceCase(int Id);

				public readonly record struct OtherCase(string Reason);

				public readonly record struct ConstructorOnlyCase(bool Flag);

				[GenerateUnion(typeof(SourceCase), typeof(OtherCase))]
				[GenerateResult]
				public readonly struct GeneratedError
				{
					readonly object? _value;

					public GeneratedError(SourceCase value) => _value = value;

					public GeneratedError(OtherCase value) => _value = value;

					public GeneratedError(ConstructorOnlyCase value) => _value = value;

					public static implicit operator GeneratedError(SourceCase value) => new(value);

					public static implicit operator GeneratedError(OtherCase value) => new(value);

					public object? Value => _value;
				}
			}
			""";

		// Act
		using var result = await GenerateAsync(
			[TestSources.GenerateUnionAttributeDeclaration, source],
			cancellationToken
		);

		// Assert
		result.AssertNoCompilationErrors();

		var generated = result.AssertSingleGeneratedSource();
		await Assert.That(generated).Contains("this global::Test.SourceCase error");
		await Assert.That(generated).Contains("this global::Test.OtherCase error");
		await Assert.That(generated).DoesNotContain("ConstructorOnlyCase");
	}

	[Test]
	public async Task GenerateAsync_GivenGenerateUnionPartialFactories_EmitsTheCaseHelpers(
		CancellationToken cancellationToken
	)
	{
		// Arrange
		// The case list is the pair of partial static factory signatures; the implementations exist only so
		// the test compilation is valid.
		const string source = """
			using Purview.Unions;

			namespace Test
			{
				public readonly record struct FactoryCase(int Id);

				public readonly record struct FactoryOtherCase(string Reason);

				[GenerateUnion]
				[GenerateResult]
				public readonly partial struct FactoryError
				{
					readonly object? _value;

					FactoryError(object? value) => _value = value;

					public static partial FactoryError FromFactoryCase(FactoryCase value);

					public static partial FactoryError FromFactoryCase(FactoryCase value) => new(value);

					public static partial FactoryError FromFactoryOtherCase(FactoryOtherCase value);

					public static partial FactoryError FromFactoryOtherCase(FactoryOtherCase value) => new(value);

					public static implicit operator FactoryError(FactoryCase value) => new(value);

					public static implicit operator FactoryError(FactoryOtherCase value) => new(value);

					public object? Value => _value;
				}
			}
			""";

		// Act
		using var result = await GenerateAsync(
			[TestSources.GenerateUnionAttributeDeclaration, source],
			cancellationToken
		);

		// Assert
		result.AssertNoCompilationErrors();
		await Assert.That(result).HasGeneratedClass("FactoryErrorResultExtensions");

		var generated = result.AssertSingleGeneratedSource();
		await Assert.That(generated).Contains("this global::Test.FactoryCase error");
		await Assert.That(generated).Contains("this global::Test.FactoryOtherCase error");
		await Assert.That(generated).Contains("extension(global::Test.FactoryError)");
	}

	[Test]
	public async Task GenerateAsync_GivenGenerateUnionNullableValueTypeAttributeCase_NormalisesToTheUnderlyingType(
		CancellationToken cancellationToken
	)
	{
		// Arrange
		// int? is exposed as int, exactly as the union generator exposes it.
		const string source = """
			using Purview.Unions;

			namespace Test
			{
				[GenerateUnion(typeof(int?))]
				[GenerateResult]
				public readonly struct NullableGeneratedError
				{
					readonly object? _value;

					NullableGeneratedError(object? value) => _value = value;

					public static implicit operator NullableGeneratedError(int value) => new(value);

					public object? Value => _value;
				}
			}
			""";

		// Act
		using var result = await GenerateAsync(
			[TestSources.GenerateUnionAttributeDeclaration, source],
			cancellationToken
		);

		// Assert
		result.AssertNoCompilationErrors();

		var generated = result.AssertSingleGeneratedSource();
		await Assert.That(generated).Contains("this int error");
		await Assert.That(generated).DoesNotContain("int?");
	}

	[Test]
	public async Task GenerateAsync_GivenGenerateUnionNullableReferenceFactoryCase_StripsTheAnnotation(
		CancellationToken cancellationToken
	)
	{
		// Arrange
		// A nullable reference annotation is not part of the case identity; typeof(string?) is illegal, so the
		// source list is the partial factory surface.
		const string source = """
			using Purview.Unions;

			namespace Test
			{
				[GenerateUnion]
				[GenerateResult]
				public readonly partial struct NullableReferenceError
				{
					readonly object? _value;

					NullableReferenceError(object? value) => _value = value;

					public static partial NullableReferenceError FromText(string? value);

					public static partial NullableReferenceError FromText(string? value) => new(value);

					public static implicit operator NullableReferenceError(string value) => new(value);

					public object? Value => _value;
				}
			}
			""";

		// Act
		using var result = await GenerateAsync(
			[TestSources.GenerateUnionAttributeDeclaration, source],
			cancellationToken
		);

		// Assert
		result.AssertNoCompilationErrors();

		var generated = result.AssertSingleGeneratedSource();
		await Assert.That(generated).Contains("this string error");
		await Assert.That(generated).DoesNotContain("string?");
	}

	[Test]
	public async Task GenerateAsync_GivenGenerateUnionAsAnIncludedCase_ExpandsItsSourceVisibleCases(
		CancellationToken cancellationToken
	)
	{
		// Arrange
		// IncludedError is a [GenerateUnion] union (no source [Union] attribute) and is a case of the outer
		// declaration union. Its Leaf case is only in its typeof list, so inclusion has to read the same
		// source-visible list.
		const string source = """
			using Purview.Unions;

			namespace Test
			{
				public readonly record struct Leaf(int Id);

				public readonly record struct Other(string Reason);

				[GenerateUnion(typeof(Leaf))]
				[GenerateResult]
				public readonly struct IncludedError
				{
					readonly object? _value;

					public IncludedError(Leaf value) => _value = value;

					public static implicit operator IncludedError(Leaf value) => new(value);

					public object? Value => _value;
				}

				[GenerateResult]
				public readonly union OuterError(IncludedError, Other);
			}
			""";

		// Act
		using var result = await GenerateAsync(
			[TestSources.GenerateUnionAttributeDeclaration, source],
			cancellationToken
		);

		// Assert
		result.AssertNoCompilationErrors();

		var outerTree = result.PrimarySyntaxTrees.Single(static tree =>
			tree.FilePath.EndsWith("OuterErrorResultExtensions.g.cs", StringComparison.Ordinal)
		);
		var outerSource = (await outerTree.GetTextAsync(cancellationToken)).ToString();

		await Assert.That(outerSource).Contains("new global::Test.OuterError(new global::Test.IncludedError(error))");
	}

	[Test]
	public async Task GenerateAsync_GivenGenerateUnionWithNoSourceVisibleCases_ReportsUnionHasNoCasesAndEmitsNoHelpers(
		CancellationToken cancellationToken
	)
	{
		// Arrange
		// The target is a union because it carries [GenerateUnion], but it has no typeof list, no partial
		// factory, no IUnionMembers provider and no source constructor, so there is no case list to read.
		const string source = """
			using Purview.Unions;

			namespace Test
			{
				[GenerateUnion]
				[GenerateResult]
				public readonly partial struct EmptyError;
			}
			""";

		// Act
		using var result = await GenerateAsync(
			[TestSources.GenerateUnionAttributeDeclaration, source],
			new ResultsSourceGeneratorTestOptions
			{
				AnalyzerTypes = [typeof(ResultsDiagnosticAnalyzer)],
				ThrowOnGenerationException = false,
			},
			cancellationToken
		);

		// Assert
		await Assert.That(result.AnalyzerResult).IsNotNull();

		var analyzerDiagnostics = result
			.AnalyzerResult!.Diagnostics.Select(static diagnostic => diagnostic.Id)
			.ToArray();

		await Assert.That(analyzerDiagnostics).Contains("RSG1001");
		await Assert.That(analyzerDiagnostics).DoesNotContain("RSG1000");
		await Assert.That(result.PrimarySyntaxTrees).IsEmpty();
	}
}
